# ==============================================================================
# Local Project Verification Script (PowerShell for Windows)
# Generated by Spring Boot Architecture Studio
# ==============================================================================
$ErrorActionPreference = "Stop"

Write-Host "====================================================" -ForegroundColor Cyan
Write-Host " Verifying Project: Demo (demo)" -ForegroundColor Cyan
Write-Host "====================================================" -ForegroundColor Cyan

# 1. Verify Java Environment
Write-Host "[INFO] Checking Java environment..." -ForegroundColor DarkCyan
try {
    $javaVersionOutput = java -version 2>&1 | Out-String
    Write-Host "[✓] Java runtime detected" -ForegroundColor Green
} catch {
    Write-Host "[✗] Java is not installed or not in PATH." -ForegroundColor Red
    Write-Host "Please install JDK 21 or higher from https://adoptium.net/"
    exit 1
}

# 2. Check Maven Wrapper
Write-Host "[INFO] Checking Maven wrapper..." -ForegroundColor DarkCyan
if (-not (Test-Path ".\mvnw.cmd")) {
    Write-Host "[✗] .\mvnw.cmd not found in current directory." -ForegroundColor Red
    exit 1
}
Write-Host "[✓] Maven wrapper ready" -ForegroundColor Green

# 4. Compile and Run Unit / Smoke Tests
Write-Host "[INFO] Compiling project and running tests via Maven..." -ForegroundColor DarkCyan
.\mvnw.cmd test
if ($LASTEXITCODE -eq 0) {
    Write-Host "[✓] All unit tests and code compilation passed!" -ForegroundColor Green
} else {
    Write-Host "[✗] Maven build / test failed." -ForegroundColor Red
    exit 1
}

Write-Host "====================================================" -ForegroundColor Green
Write-Host "✓ PROJECT VERIFIED AND READY TO RUN" -ForegroundColor Green
Write-Host "====================================================" -ForegroundColor Green
Write-Host "To start the application, run:"
Write-Host "  .\mvnw.cmd spring-boot:run" -ForegroundColor Cyan
Write-Host "===================================================="
